import{_ as s,o as t,c as n,aN as e}from"./chunks/framework.D31DlcCL.js";const r="/img/math-shape-folding.svg",g=JSON.parse('{"title":"折出来的奥秘：图形的折叠与对称","description":"动手折一折，你会发现图形隐藏的另一面。本文带你探索折叠中的数学规律：重合、对称与折痕。","frontmatter":{"title":"折出来的奥秘：图形的折叠与对称","date":"2026-02-10T11:00:00.000Z","categories":["数学"],"tags":["小学数学","折叠问题","轴对称","空间观念"],"description":"动手折一折，你会发现图形隐藏的另一面。本文带你探索折叠中的数学规律：重合、对称与折痕。","cover":"/img/math-shape-folding.svg","top_img":"/img/math-shape-folding.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-shape-folding.md","filePath":"posts/primary-math-shape-folding.md","lastUpdated":null}'),o={name:"posts/primary-math-shape-folding.md"};function l(i,a,m,p,h,c){return t(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="折出来的奥秘-图形的折叠与对称" tabindex="-1">折出来的奥秘：图形的折叠与对称 <a class="header-anchor" href="#折出来的奥秘-图形的折叠与对称" aria-label="Permalink to &quot;折出来的奥秘：图形的折叠与对称&quot;">​</a></h1><p>你玩过纸飞机或者折纸吗？每一次翻折，其实都在改变图形的形状。在数学里，<strong>“折叠”</strong>（Folding）不仅是一种手工，更是一个研究对称和重合的重要工具。</p><hr><h2 id="一、-折叠的本质-寻找-双胞胎" tabindex="-1">一、 折叠的本质：寻找“双胞胎” <a class="header-anchor" href="#一、-折叠的本质-寻找-双胞胎" aria-label="Permalink to &quot;一、 折叠的本质：寻找“双胞胎”&quot;">​</a></h2><p>当你把一张纸对折时，折痕两边的部分会完全重叠。</p><p><img src="'+r+'" alt="图形折叠图解"></p><p><strong>【核心规律】</strong>：</p><ol><li><strong>重合性</strong>：折叠后完全重叠的两个部分，它们的形状、大小、长短都是<strong>完全一样</strong>的。</li><li><strong>折痕（对称轴）</strong>：那条被折出来的印子，就是这个图形的<strong>对称轴</strong>。</li></ol><hr><h2 id="二、-常见的折叠小实验" tabindex="-1">二、 常见的折叠小实验 <a class="header-anchor" href="#二、-常见的折叠小实验" aria-label="Permalink to &quot;二、 常见的折叠小实验&quot;">​</a></h2><h3 id="_1-对折找中心" tabindex="-1">1. 对折找中心 <a class="header-anchor" href="#_1-对折找中心" aria-label="Permalink to &quot;1. 对折找中心&quot;">​</a></h3><p>拿一个圆形纸片，任意对折两次，两条折痕的交点就是圆的中心。</p><h3 id="_2-长方形变正方形" tabindex="-1">2. 长方形变正方形 <a class="header-anchor" href="#_2-长方形变正方形" aria-label="Permalink to &quot;2. 长方形变正方形&quot;">​</a></h3><p>拿一张长方形纸，把短边往长边上折，使它们重合。多出来的部分剪掉，展开后你就会得到一个完美的<strong>正方形</strong>！</p><hr><h2 id="三、-折叠中的-陷阱" tabindex="-1">三、 折叠中的“陷阱” <a class="header-anchor" href="#三、-折叠中的-陷阱" aria-label="Permalink to &quot;三、 折叠中的“陷阱”&quot;">​</a></h2><p>很多小朋友在想象折叠后的样子时会出错。</p><ul><li><strong>镜像原理</strong>：左边的东西折过去会变成右边，而且方向会反过来。</li><li><strong>长度不变</strong>：虽然折叠后看起来图形变小了，但原来的边长和角的大小在展开后还是不变的。</li></ul><hr><h2 id="四、-经典例题-数一数有几层" tabindex="-1">四、 经典例题：数一数有几层 <a class="header-anchor" href="#四、-经典例题-数一数有几层" aria-label="Permalink to &quot;四、 经典例题：数一数有几层&quot;">​</a></h2><p><strong>题目</strong>：一张纸对折 1 次有 2 层，对折 2 次有 4 层。请问对折 3 次后有几层？</p><p><strong>解析</strong>：</p><ul><li>对折 1 次：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span></span></span></span></li><li>对折 2 次：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">2 \\times 2 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span></li><li>对折 3 次：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">4 \\times 2 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span><strong>规律</strong>：每对折一次，层数就<strong>翻一倍</strong>。</li></ul><hr><h2 id="五、-练一练-动手实验室" tabindex="-1">五、 练一练（动手实验室） <a class="header-anchor" href="#五、-练一练-动手实验室" aria-label="Permalink to &quot;五、 练一练（动手实验室）&quot;">​</a></h2><ol><li><strong>找对称轴</strong>：拿出一个心形、一个等腰三角形和一个长方形，分别折一折，看看它们各有几条对称轴？</li><li><strong>折纸猜图</strong>：把一张正方形纸对折，在折痕处剪一个小半圆，展开后会是一个什么图形？</li><li><strong>超级折叠</strong>：如果你能把一张纸对折 7 次（虽然很难），猜猜它会有多少层？（答案是 128 层！）</li></ol><hr><p><em>总结：折叠是连接二维平面和三维想象的桥梁。多动动手，你的空间感会越来越棒！</em></p>',28)])])}const u=s(o,[["render",l]]);export{g as __pageData,u as default};
